#include <iostream>
#include <string_view>

// Emulate mystery1 (strcat), mystery2 (strlen), and mystery3 (streq)
void customStrcat(char* dest, const char* src) {
    while (*dest != '\0') {
        ++dest;
    }
    while ((*dest = *src) != '\0') {
        ++dest;
        ++src;
    }
}

std::size_t customStrlen(const char* s) {
    std::size_t len = 0;
    for (; *s != '\0'; ++s) {
        ++len;
    }
    return len;
}

bool customStreq(const char* s1, const char* s2) {
    while (*s1 != '\0' && *s2 != '\0') {
        if (*s1 != *s2) {
            return false;
        }
        ++s1;
        ++s2;
    }
    return *s1 == *s2; // Both must terminate together
}

int main() {
    char buffer[64] = "Antigravity";
    const char appendText[] = "C++";

    std::cout << "Initial length: " << customStrlen(buffer) << '\n';
    customStrcat(buffer, appendText);
    std::cout << "Concatenated: " << buffer << '\n';
    std::cout << "Is equal to AntigravityC++? " 
              << std::boolalpha << customStreq(buffer, "AntigravityC++") << '\n';

