#include <iostream>
#include <vector>
#include <array>

// Demonstrating function pointer dispatch table (Exercise 7.25 concept)
using ActionFn = void (*)(int);

void printDouble(int val) { std::cout << "Double: " << val * 2 << '\n'; }
void printSquare(int val) { std::cout << "Square: " << val * val << '\n'; }
void printNegate(int val) { std::cout << "Negate: " << -val << '\n'; }

// Minimal Simpletron Machine Language (SML) virtual machine runner
void runSML(std::array<int, 100>& memory) {
    int accumulator = 0;
    size_t instructionCounter = 0;

    while (instructionCounter < memory.size()) {
        int instruction = memory[instructionCounter];
        int opcode = instruction / 100;
        int operand = instruction % 100;

        ++instructionCounter;

        switch (opcode) {
            case 20: // LOAD
                accumulator = memory[operand];
                break;
            case 30: // ADD
                accumulator += memory[operand];
                break;
            case 21: // STORE
                memory[operand] = accumulator;
                break;
            case 11: // WRITE
                std::cout << "SML Output: " << memory[operand] << '\n';
                break;
            case 43: // HALT
                return;
            default:
                break;
        }
    }
}

int main() {
    // Function pointer jump table
    std::array<ActionFn, 3> menu = {printDouble, printSquare, printNegate};
    int testValue = 5;
    for (size_t choice = 0; choice < menu.size(); ++choice) {
        menu[choice](testValue);
    }

    // Simpletron SML Program (computes A + B and prints result)
    std::array<int, 100> memory{};
    memory[0] = 2005; // LOAD from location 05
    memory[1] = 3006; // ADD from location 06
    memory[2] = 2107; // STORE into location 07
    memory[3] = 1107; // WRITE from location 07
    memory[4] = 4300; // HALT
    memory[5] = 35;   // Data Variable A
    memory[6] = 15;   // Data Variable B

    runSML(memory);
    return 0;
}
